function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 1000) return 's needs 1 to 1000 characters.';
  if (!/^[0-9]+$/.test(s)) return 's may contain only the digits 0 to 9.';
  return null;
}

