function equalDigitFrequency(s) {
  const seen = new Set();
  for (let start = 0; start < s.length; start++) {
    const count = new Array(10).fill(0);
    let distinct = 0;
    let maxFreq = 0;
    for (let end = start; end < s.length; end++) {
      const digit = s.charCodeAt(end) - 48;
      if (count[digit] === 0) {
        distinct++;
      }
      count[digit]++;
      maxFreq = Math.max(maxFreq, count[digit]);
      if (maxFreq * distinct === end - start + 1) {
        seen.add(s.slice(start, end + 1));
      }
    }
  }
  return seen.size;
}

