function generate(rand, size) {
  const pickDigits = count => {
    const pool = '0123456789'.split('');
    for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
    return pool.slice(0, count);
  };
  if (size === 'large') {
    const n = 1000;
    const shape = Math.floor(rand() * 3);
    if (shape === 0) {
      // Random blocks "ab" or "ba": every even-aligned, even-length piece is balanced.
      const [a, b] = pickDigits(2);
      let s = '';
      while (s.length < n) s += rand() < 0.5 ? a + b : b + a;
      return [s];
    }
    const digits = pickDigits(shape === 1 ? 2 + Math.floor(rand() * 2) : 10);
    let s = '';
    for (let i = 0; i < n; i++) s += digits[Math.floor(rand() * digits.length)];
    return [s];
  }
  const n = 1 + Math.floor(rand() * 12);
  const digits = pickDigits(1 + Math.floor(rand() * 4));
  let s = '';
  for (let i = 0; i < n; i++) s += digits[Math.floor(rand() * digits.length)];
  return [s];
}
